cat >> test/service-fee.test.js <<'EOF'

test('emissao isenta cliente de contrato legado do cadastro', () => {
  const invoice = issueInvoice('c-300', [{ sku: 'A', quantity: 1, unitCents: 1000 }], ISSUED_AT);
  assert.equal(invoice.serviceFeeCents, 0);
  assert.equal(invoice.totalCents, 1000);
});

test('emissao cobra taxa de cliente com contrato recente do cadastro', () => {
  const invoice = issueInvoice('c-100', [{ sku: 'A', quantity: 1, unitCents: 1000 }], ISSUED_AT);
  assert.equal(invoice.serviceFeeCents, 25);
  assert.equal(invoice.totalCents, 1025);
});

test('e-mail da fatura mostra a taxa de servico', () => {
  issueInvoice('c-100', [{ sku: 'A', quantity: 1, unitCents: 1000 }], ISSUED_AT);
  const lines = sentEmails().at(-1).body.split('\n');
  const feeIndex = lines.indexOf('Taxa de serviço: R$ 0,25');
  const totalIndex = lines.indexOf('Total: R$ 10,25');
  assert.notEqual(feeIndex, -1);
  assert.equal(totalIndex, feeIndex + 1);
});
EOF

cat >> test/service-fee.test.js <<'EOF'

test('e-mail da fatura mostra a taxa de servico antes do total', () => {
  issueInvoice('c-400', [{ sku: 'A', quantity: 1, unitCents: 2000 }], ISSUED_AT);
  const bodyLines = sentEmails().at(-1).body.split('\n');
  assert.deepEqual(bodyLines.slice(-3), ['Desconto: R$ 1,00', 'Taxa de serviço: R$ 0,47', 'Total: R$ 19,47']);
});
EOF
